function PartnerCard({ p }) {
  const [open, setOpen] = useState(false);
  // New (category-first, 2026-06) entities carry flat fields; old (company-first)
  // weeks carry rows[]/actions[]. Support both so the week-nav history renders.
  const legacy = Array.isArray(p.rows);
  const last = legacy ? p.rows.find(r => /last engagement/i.test(r.topic)) : null;
  const phase = legacy ? p.rows.find(r => /project phase|phase/i.test(r.topic)) : null;
  const freshIso = legacy ? last?.date_iso : p.date_iso;
  const engageDate = legacy ? last?.date_raw : p.date_raw;
  const engageText = legacy ? last?.content : p.last_engagement;
  const statusText = legacy ? phase?.content : p.status;
  const expandable = legacy && p.rows.length > 0;   // only old weeks have a rows table to reveal
  return (
    <div className="dv-card dv-card--partner">
      <div className="dv-card-head" onClick={() => expandable && setOpen(v => !v)} style={{ cursor: expandable ? 'pointer' : 'default' }}>
        <FreshnessDot iso={freshIso} />
        <span className="dv-card-name">{p.name}</span>
        {p.group && <span className="dv-badge">{p.group.replace(/\s*\*.*\*$/, '')}</span>}
        {expandable && <span className="dv-card-caret">{open ? '▾' : '▸'}</span>}
      </div>
      {p.descriptor && <div className="dv-card-desc">{p.descriptor}</div>}
      {engageText && <div className="dv-card-line"><span className="dv-key">{engageDate || 'Last'}:</span> {engageText}</div>}
      {statusText && (!legacy || !open) && <div className="dv-card-line"><span className="dv-key">Status:</span> {statusText}</div>}
      {open && expandable && (
        <>
          <table className="dv-table">
            <tbody>
              {p.rows.map((r, i) => (
                <tr key={i}><td className="dv-key">{r.topic}</td><td>{r.content}</td><td className="dv-date">{r.date_raw}</td></tr>
              ))}
            </tbody>
          </table>
          {p.actions && p.actions.length > 0 && (
            <ul className="dv-actions">
              {p.actions.map((a, i) => (
                <li key={i} className={a.external ? 'dv-action--ext' : ''}>
                  {a.external && <span className="dv-badge dv-badge--ext">ext</span>} {a.item}
                </li>
              ))}
            </ul>
          )}
        </>
      )}
    </div>
  );
}

function SectionTable({ rows }) {
  if (!rows || rows.length === 0) return null;
  const keys = Object.keys(rows[0]).filter(k => !k.endsWith('_iso'));
  return (
    <table className="dv-table dv-table--full">
      <thead><tr>{keys.map(k => <th key={k}>{k.replace(/_/g, ' ')}</th>)}</tr></thead>
      <tbody>
        {rows.map((r, i) => (
          <tr key={i}>{keys.map(k => <td key={k}>{r[k]}</td>)}</tr>
        ))}
      </tbody>
    </table>
  );
}

// Render the displayed week's Sales & Operations sync to PDF. The server shells
// out to scripts/sync-report-pdf.js for the given week (YYYYMMDD); if `week` is
// missing/malformed it omits the arg and the script falls back to the latest week.
// status: idle | rendering | done | locked | error
function RenderPdfButton({ week }) {
  const { selectFile } = useDashboard();
  const [pdf, setPdf] = useState({ status: 'idle', msg: '' });
  const resetTimer = useRef(null);
  const wk = /^\d{8}$/.test(String(week || '')) ? String(week) : null;

  // One pending auto-reset at a time: a new render cancels the prior render's
  // reset so a stale 6 s timer can't blank a fresh result early; cleared on unmount.
  useEffect(() => () => clearTimeout(resetTimer.current), []);

  const renderPdf = async () => {
    if (pdf.status === 'rendering') return;
    clearTimeout(resetTimer.current);
    setPdf({ status: 'rendering', msg: '' });
    try {
      const res = await fetch('/api/render-pdf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(wk ? { week: wk } : {}),
      });
      const raw = await res.text();
      let resp = {};
      try { resp = JSON.parse(raw); } catch { /* non-JSON (e.g. 404 HTML) */ }
      if (res.ok) {
        setPdf({ status: 'done', msg: resp.message || 'PDF written' });
        // Auto-open the freshly rendered PDF in the right-hand FileViewer.
        if (resp.pdfPath) selectFile(resp.pdfPath);
      } else if (res.status === 404) {
        setPdf({ status: 'error', msg: 'Endpoint not found (HTTP 404) — restart the dashboard server so /api/render-pdf loads' });
      } else if (res.status === 423 || resp.locked) {
        setPdf({ status: 'locked', msg: 'PDF is open/locked — close the viewer and retry' });
      } else {
        setPdf({ status: 'error', msg: resp.message || `Render failed (HTTP ${res.status})` });
      }
    } catch (e) {
      setPdf({ status: 'error', msg: String(e.message || e) });
    }
    resetTimer.current = setTimeout(() => setPdf(p => (p.status === 'rendering' ? p : { status: 'idle', msg: '' })), 6000);
  };

  const label = pdf.status === 'rendering' ? 'Rendering…'
    : pdf.status === 'done' ? '✓ PDF saved'
    : pdf.status === 'locked' ? '⚠ PDF locked'
    : pdf.status === 'error' ? '✕ PDF failed'
    : '⤓ Render PDF';
  const stateClass = pdf.status === 'done' ? 'dv-pdfbtn--done'
    : pdf.status === 'locked' ? 'dv-pdfbtn--locked'
    : pdf.status === 'error' ? 'dv-pdfbtn--error'
    : '';

  return (
    <>
      <button
        className={`dv-pdfbtn ${stateClass}`}
        onClick={renderPdf}
        disabled={pdf.status === 'rendering'}
        title={pdf.msg || (wk ? `Render the week of ${week} to PDF` : 'Render the latest weekly Sales & Operations sync to PDF')}
      >
        {label}
      </button>
      {(pdf.status === 'error' || pdf.status === 'locked') && pdf.msg && (
        <span className={`dv-pdfmsg dv-pdfmsg--${pdf.status}`} title={pdf.msg}>
          {pdf.msg}
        </span>
      )}
    </>
  );
}

// ---------------------------------------------------------------------------
// Sync — verticals view
//
// The category-first weekly sync (Sync_Content_Schema §J) tags every
// SALES/OPERATIONS entity with a `group` like "FOUNDRY — Design" /
// "EQUIPMENT — Testers". This view pivots those rows into the 2026 website's
// product lenses — the "how we sell" view, complementing the company-first
// Projects tab (which stays entity-centric). It splits each group on the
// em-dash " — " (left = vertical, right = focus) and lays the entities out as
// four lanes, each an accordion per focus group. PartnerCard/FreshnessDot are
// reused unchanged; the flat list stays the default and the fallback.
// ---------------------------------------------------------------------------

// The four product lanes (mirror the website verticals). `accent` colours echo
// the graph layer-hue family (blue→violet→cyan→magenta) and deliberately avoid
// the green/amber/red of FreshnessDot, so a lane accent never reads as a
// freshness signal.
const VERTICAL_LANES = [
  { key: 'EQUIPMENT', label: 'Equipment', accent: '#3b82f6' },
  { key: 'FOUNDRY',   label: 'Foundry',   accent: '#8b5cf6' },
  { key: 'PRODUCTS',  label: 'Products',  accent: '#06b6d4' },
  { key: 'AI',        label: 'AI',        accent: '#ec4899' },
];

// Canonical focus order within each lane. Any focus not listed sorts after these
// alphabetically, so a newly-introduced focus group still appears (at the end).
const FOCUS_ORDER = {
  EQUIPMENT: ['Testers', 'DLW', 'Strategic & Equipment Placement'],
  FOUNDRY:   ['Design', 'Fabrication', 'Capex / Internal'],
  PRODUCTS:  ['Consumer Devices', 'Camera Modules'],
  AI:        ['AI & Software'],
};

// Split a sync `group` into { lane, focus }. Most groups are "VERTICAL — Focus".
// Two carry no " — " separator and no website vertical of their own:
//   • "AI & SOFTWARE"               → the AI lane, single "AI & Software" focus.
//   • "STRATEGIC & EQUIPMENT PLACEMENT" → FOLDED INTO the Equipment lane as its own
//     "Strategic & Equipment Placement" focus accordion. Rationale: these are
//     research/strategic partners HOSTING a MOT tool (a DLW or tester), so the
//     loaned artefact is MOT *equipment* — the Equipment lane is its natural
//     home. It stays a separate accordion (not merged into Testers/DLW) because
//     it is a relationship type, not a sales focus. Folding here keeps the
//     deliberate four-lane layout rather than spawning a lone 5th lane for the
//     one group that maps to no website vertical.
function laneAndFocus(group) {
  if (!group) return { lane: null, focus: null };
  const parts = group.split(/\s*—\s*/);             // em-dash separator
  const vertical = (parts[0] || '').trim();
  const focus = parts.slice(1).join(' — ').trim();  // keep a focus that itself had a dash
  const v = vertical.toUpperCase();
  if (v.startsWith('STRATEGIC')) return { lane: 'EQUIPMENT', focus: 'Strategic & Equipment Placement' };
  if (v.startsWith('FOUNDRY'))   return { lane: 'FOUNDRY',   focus: focus || 'Design' };
  if (v.startsWith('EQUIPMENT')) return { lane: 'EQUIPMENT', focus: focus || 'General' };
  if (v.startsWith('PRODUCTS'))  return { lane: 'PRODUCTS',  focus: focus || 'General' };
  if (v.startsWith('AI'))        return { lane: 'AI',        focus: focus || 'AI & Software' };
  return { lane: null, focus: focus || vertical || null };
}

function orderedFocuses(laneKey, focuses) {
  const order = FOCUS_ORDER[laneKey] || [];
  const inOrder = order.filter(f => focuses.includes(f));
  const extras = focuses.filter(f => !order.includes(f)).sort();
  return [...inOrder, ...extras];
}

// One focus group inside a lane — a collapsible list of PartnerCards. Open state
// persists per (section, lane, focus) so it survives reloads and week switches.
function FocusAccordion({ storageKey, label, partners }) {
  const [open, setOpen] = usePersistentState(storageKey, true);
  return (
    <div className="dv-facc">
      <button className="dv-facc-head" onClick={() => setOpen(o => !o)} aria-expanded={open}>
        <span className="dv-facc-caret">{open ? '▾' : '▸'}</span>
        <span className="dv-facc-label">{label}</span>
        <span className="dv-count">{partners.length}</span>
      </button>
      {open && (
        <div className="dv-facc-body">
          {partners.map(p => <PartnerCard key={(p.group || '') + p.name} p={p} />)}
        </div>
      )}
    </div>
  );
}

// Four product lanes for one grouped section's partners. Entities whose group is
// unrecognised / missing fall into a full-width "Other" strip below the lanes
// rather than being silently dropped.
function VerticalLanes({ sectionName, partners }) {
  const { byLane, ungrouped } = useMemo(() => {
    const byLane = {};
    for (const lane of VERTICAL_LANES) byLane[lane.key] = {};
    const ungrouped = [];
    for (const p of partners) {
      const { lane, focus } = laneAndFocus(p.group);
      if (!lane || !byLane[lane]) { ungrouped.push(p); continue; }
      const f = focus || 'General';
      (byLane[lane][f] ||= []).push(p);
    }
    return { byLane, ungrouped };
  }, [partners]);

  return (
    <>
      <div className="dv-vlanes">
        {VERTICAL_LANES.map(lane => {
          const groups = byLane[lane.key];
          const focuses = orderedFocuses(lane.key, Object.keys(groups));
          const total = focuses.reduce((n, f) => n + groups[f].length, 0);
          return (
            <div key={lane.key} className="dv-vlane" style={{ '--lane-accent': lane.accent }}>
              <div className="dv-vlane-head">
                <span className="dv-vlane-title">{lane.label}</span>
                <span className="dv-count">{total}</span>
              </div>
              {focuses.length === 0
                ? <div className="dv-vlane-empty">No active entries this week</div>
                : focuses.map(focus => (
                    <FocusAccordion
                      key={focus}
                      storageKey={`sync-vert-acc:${sectionName}:${lane.key}:${focus}`}
                      label={focus}
                      partners={groups[focus]}
                    />
                  ))}
            </div>
          );
        })}
      </div>
      {ungrouped.length > 0 && (
        <div className="dv-vlane dv-vlane--ungrouped" style={{ '--lane-accent': 'var(--text-muted)' }}>
          <div className="dv-vlane-head">
            <span className="dv-vlane-title">Other</span>
            <span className="dv-count">{ungrouped.length}</span>
          </div>
          <div className="dv-facc-body">
            {ungrouped.map(p => <PartnerCard key={(p.group || '') + p.name} p={p} />)}
          </div>
        </div>
      )}
    </>
  );
}

// Sort a section's partner cards for the Sync tab. `default` keeps document
// order; date sorts push undated rows last; `importance` uses a project-tier
// lookup (tierFn, built from projects.json) so focus accounts surface first.
// Returns the same array reference for `default` so React skips needless work.
function sortSyncPartners(partners, sort, tierFn) {
  if (!sort || sort === 'default') return partners;
  const byName = (a, b) => a.name.localeCompare(b.name);
  const arr = [...partners];
  if (sort === 'name') arr.sort(byName);
  else if (sort === 'importance') arr.sort((a, b) =>
    (tierFn(a.name) || 9) - (tierFn(b.name) || 9) || (b.date_iso || '').localeCompare(a.date_iso || '') || byName(a, b));
  else { // newest | oldest — undated rows always last
    const dir = sort === 'oldest' ? 1 : -1;
    arr.sort((a, b) => {
      const da = a.date_iso, db = b.date_iso;
      if (!da && !db) return byName(a, b);
      if (!da) return 1;
      if (!db) return -1;
      return dir * da.localeCompare(db) || byName(a, b);
    });
  }
  return arr;
}

export function SyncView() {
  const { selectFile } = useDashboard();
  const [mode, setMode] = usePersistentState('sync-view-mode', 'flat');  // flat (default) ↔ verticals
  // Published weeks, newest → oldest (from sync-weeks.json). weeks[0] is the
  // current/active week; default the selector to it. Per-week sync content
  // lives at /api/data/sync/<week>.json (sync.json is the latest, kept as a
  // fallback until the index loads).
  const [weeksData] = useData('sync-weeks');
  const weeks = Array.isArray(weeksData?.weeks) ? weeksData.weeks : [];
  const activeWeek = weeks[0]?.week || null;
  const [viewWeek, setViewWeek] = useState(null);   // null → the current (newest) week
  const week = viewWeek || activeWeek;
  const [data, error, reload] = useData(week ? `sync/${week}` : 'sync');
  const [sort, setSort] = usePersistentState('sync-sort', 'default'); // default|newest|oldest|importance|name
  const [projData] = useData('projects');           // for the "importance" sort (project tier by name)
  const tierFn = useMemo(() => {
    const idx = new Map();
    for (const p of (projData?.projects || [])) if (p.tier != null) idx.set(normName(p.name), p.tier);
    return (name) => {
      const n = normName(name);
      if (idx.has(n)) return idx.get(n);
      const nt = n.split(' ').filter(x => x.length > 2);   // token-overlap fallback (e.g. "ST Micro" → STMicro…)
      for (const [k, t] of idx) { const kt = k.split(' '); if (kt.some(x => x.length > 2 && nt.includes(x))) return t; }
      return 9;                                            // unmatched (e.g. OPERATIONS workstreams) sort last
    };
  }, [projData]);
  if (isNotConfigured(error)) return <EmptyState view="Sync" />;
  if (error) return <div className="dv-error">{error}</div>;
  if (!data) return <div className="dv-loading">Loading sync…</div>;

  const curWeek = week || data.week;
  const idx = weeks.findIndex(w => w.week === curWeek);   // -1 until the index loads
  const isCurrent = idx <= 0;                              // newest week (or single-file fallback)
  const isDraft = idx >= 0 ? !!weeks[idx].draft : !!data.draft;  // ongoing in-preparation week

  return (
    <div className="dv-root">
      <div className="dv-toolbar">
        <span className="dv-title">Sales &amp; Operations sync</span>
        <div className="dv-weeknav">
          <button className="dv-weekbtn" disabled={idx < 0 || idx >= weeks.length - 1}
            title="Older week" onClick={() => setViewWeek(weeks[idx + 1].week)}>◀</button>
          <span className="dv-weeklabel">week of {weekIso(curWeek)}{isDraft && ' · draft'}</span>
          <button className="dv-weekbtn" disabled={idx <= 0}
            title="Newer week" onClick={() => setViewWeek(weeks[idx - 1].week)}>▶</button>
        </div>
        <div className="dv-seg" role="group" aria-label="Sync layout">
          <button className={`dv-segbtn ${mode === 'flat' ? 'dv-segbtn--on' : ''}`}
            onClick={() => setMode('flat')} title="Flat list — every entity under its section">Flat</button>
          <button className={`dv-segbtn ${mode === 'verticals' ? 'dv-segbtn--on' : ''}`}
            onClick={() => setMode('verticals')}
            title="Verticals — group SALES/OPERATIONS by product lane (Equipment / Foundry / Products / AI)">Verticals</button>
        </div>
        <label className="dv-field">Sort
          <select className="dv-select" value={sort} onChange={e => setSort(e.target.value)}
            title="Sort partner cards within each section / focus group">
            <option value="default">Default</option>
            <option value="newest">Newest</option>
            <option value="oldest">Oldest</option>
            <option value="importance">Importance</option>
            <option value="name">Name (A–Z)</option>
          </select>
        </label>
        <button className="dv-chip" onClick={() => selectFile(data.source)}>open report</button>
        {!isDraft && <RenderPdfButton week={data.week} />}
        <GeneratedStamp data={data} onReload={reload} />
        {isDraft
          ? <span className="dv-stamp">in preparation — not yet published</span>
          : !isCurrent && <span className="dv-stamp">viewing an earlier published week</span>}
      </div>
      {data.sections.map(sec => {
        const partners = sortSyncPartners(sec.partners, sort, tierFn);
        return (
        <div key={sec.name} className="dv-section">
          <h2 className="dv-h2">{sec.name}</h2>
          {sec.descriptor && <div className="dv-card-desc">{sec.descriptor}</div>}
          {sec.bulletGroups && sec.bulletGroups.length > 0 ? (
            sec.bulletGroups.map((g, gi) => (
              <div key={gi} className="dv-bulletgroup">
                <h3 className="dv-h3">{g.label}</h3>
                <ul className="dv-bullets">{g.items.map((b, i) => <li key={i}>{b}</li>)}</ul>
              </div>
            ))
          ) : sec.bullets.length > 0 && (
            <ul className="dv-bullets">{sec.bullets.map((b, i) => <li key={i}>{b}</li>)}</ul>
          )}
          <SectionTable rows={sec.table} />
          {/* DIRECTION / EVENTS / GENERAL / Backlog tables carry no `group`, so
              their partners[] is empty — this branch only affects SALES /
              OPERATIONS. Flat is the default + the fallback for any week. */}
          {partners.length > 0 && (
            mode === 'verticals'
              ? <VerticalLanes sectionName={sec.name} partners={partners} />
              : (
                <div className="dv-cardgrid">
                  {partners.map(p => <PartnerCard key={(p.group || '') + p.name} p={p} />)}
                </div>
              )
          )}
        </div>
        );
      })}
    </div>
  );
}

// ---------------------------------------------------------------------------
// To-Do — person columns + external pending + key dates
// ---------------------------------------------------------------------------

// A source to-do section whose name matches this is the team / unassigned
// bucket (e.g. "## Unassigned / team"). It becomes the pinned first column
// rather than a per-person column — and we never synthesize a second one.
const TEAM_RE = /unassigned|team/i;

// Week-id math (YYYYMMDD). Browser Date is fine here (not a workflow script).
function shiftWeek(weekId, days) {
  const dt = new Date(+weekId.slice(0, 4), +weekId.slice(4, 6) - 1, +weekId.slice(6, 8));
  dt.setDate(dt.getDate() + days);
  const p = n => String(n).padStart(2, '0');
  return `${dt.getFullYear()}${p(dt.getMonth() + 1)}${p(dt.getDate())}`;
}
const weekIso = weekId => `${weekId.slice(0, 4)}-${weekId.slice(4, 6)}-${weekId.slice(6, 8)}`;

export function TodosView() {
  const { selectFile } = useDashboard();
  const [data, error, reload] = useData('todos');
  const [store, setStore] = useState({ version: 2, weeks: {} }); // week-scoped overlay
  const [viewWeek, setViewWeek] = useState(null);    // null → the active (current) week
  const [dragOver, setDragOver] = useState(null);    // owner column under cursor
  const [hideClosed, setHideClosed] = useState(false); // hide resolved + deleted
  const [showRemoved, setShowRemoved] = useState(false); // reveal tasks confirmed-removed from the report
  const [addingIn, setAddingIn] = useState(null);    // owner whose add-task input is open
  const [newText, setNewText] = useState('');
  const dragged = useRef(null);                      // {id, text, basePerson}
  const dragGhost = useRef(null);                    // detached solid drag-image element
  const grabOffset = useRef({ x: 0, y: 0 });         // cursor offset within the grabbed tile
  const addCancel = useRef(false);                   // Esc pressed → blur should not create

  // Load the durable overlay (not cached — it mutates as we edit).
  useEffect(() => {
    fetch('/api/assignments')
      .then(r => r.ok ? r.json() : { weeks: {} })
      .then(d => setStore(d.weeks ? d : { version: 2, weeks: {} }))
      .catch(() => setStore({ version: 2, weeks: {} }));
  }, []);

  const activeWeek = data?.week || null;             // the week todos.json projects
  const week = viewWeek || activeWeek;               // currently viewed week
  const isFuture = !!(week && activeWeek && week > activeWeek);
  const edits = (week && store.weeks?.[week]?.edits) || {};   // this week's deltas

  // The canonical team bucket: the existing source section if there is one,
  // else a synthetic "Unassigned" label. Dropping on the first column writes
  // this exact value, so propagation maps it straight back to that heading.
  const team = useMemo(
    () => (data ? Object.keys(data.by_person).find(k => TEAM_RE.test(k)) || 'Unassigned' : 'Unassigned'),
    [data]);

  // Base tasks for the *active* week, straight from the markdown projection.
  const activeBase = useMemo(() => {
    if (!data) return [];
    return Object.entries(data.by_person).flatMap(([basePerson, items]) =>
      // Back-compat: pre-id extracts stored bare strings.
      items.map(it => typeof it === 'string'
        ? { id: null, text: it, basePerson }
        : { id: it.id, text: it.text, basePerson }));
  }, [data]);

  // Base for the viewed week. The active week uses the markdown projection; a
  // future week previews the carry-over: the active week's still-open tasks at
  // their current owner. Tasks resolved or deleted this week fall off here — the
  // publish-gated removal the report needs (they stay green in the active week).
  const baseForView = useMemo(() => {
    if (!data || !week) return [];
    if (week <= activeWeek) return activeBase;
    const e = store.weeks?.[activeWeek]?.edits || {};
    const dropped = new Set(Object.values(e).filter(x => x.deleted || x.dismissed || x.status === 'done').map(x => x.id));
    const own = t => (t.id && e[t.id]?.to) || t.basePerson;
    const created = Object.values(e).filter(x => x.created && !x.deleted && x.status !== 'done')
      .map(x => ({ id: x.id, text: x.text, basePerson: x.to }));
    return [...activeBase, ...created]
      .filter(t => !t.id || !dropped.has(t.id))
      .map(t => ({ id: t.id, text: t.text, basePerson: own(t) }));
  }, [data, week, activeWeek, activeBase, store]);

  // Layer this week's overlay on the base, then append created tasks. Deleted
  // tasks stay visible (shaded red) until the next publish drops them; they're
  // only removed from a *future* week's carry-over (handled in baseForView).
  const tasks = useMemo(() => {
    const created = Object.values(edits)
      .filter(a => a.created)
      .map(a => ({ id: a.id, text: a.text, basePerson: a.to, created: true }));
    return [...baseForView, ...created];
  }, [baseForView, edits]);

  const ownerOf = t => (t.id && edits[t.id]?.to) || t.basePerson;
  const isDone = t => t.id && edits[t.id]?.status === 'done';
  const isDeleted = t => t.id && edits[t.id]?.deleted;
  const isDismissed = t => t.id && edits[t.id]?.dismissed;   // step-2 confirmed: off the report now

  // Column order: team first (pinned), then the agent's people, then any owner
  // an overlay edit introduced. Single row — horizontal scroll past the pin.
  const columns = useMemo(() => {
    if (!data) return [];
    const people = Object.keys(data.by_person).filter(p => p !== team);
    for (const a of Object.values(edits)) if (a.to && a.to !== team && !people.includes(a.to)) people.push(a.to);
    return [team, ...people];
  }, [data, edits, team]);

  const pending = Object.values(edits).filter(a => !a.propagated).length;
  const removedCount = tasks.filter(t => isDismissed(t)).length;

  // Mirror of the server's applyOp on one week's edit map: optimistically merge
  // a delta and prune it if it reverts to base, so the UI matches what persists.
  function applyEditsLocal(prevEdits, op) {
    const next = { ...prevEdits };
    const id = op.id;
    const cur = next[id] || {};
    const merged = {
      id,
      text: op.text ?? cur.text ?? '',
      from: op.from ?? cur.from ?? null,
      to: op.to ?? cur.to ?? null,
      status: op.status ?? cur.status ?? 'open',
      created: op.created ?? cur.created ?? false,
      deleted: op.deleted ?? cur.deleted ?? false,
      dismissed: op.dismissed ?? cur.dismissed ?? false,
      propagated: false,
    };
    const noop = !merged.created && !merged.deleted && !merged.dismissed && merged.status === 'open' && merged.to === merged.from;
    if (noop) delete next[id]; else next[id] = merged;
    return next;
  }

  // Post an edit tagged to the viewed week; optimistic when the id is known,
  // otherwise (create) wait for the server to mint it. Reconciles with the response.
  function postOp(op) {
    op = { ...op, week };
    if (op.id) setStore(prev => {
      const next = { ...prev, weeks: { ...prev.weeks } };
      const bucket = { published: false, ...(next.weeks[week] || {}) };
      bucket.edits = applyEditsLocal({ ...(bucket.edits || {}) }, op);
      next.weeks[week] = bucket;
      return next;
    });
    fetch('/api/assignments', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(op),
    })
      .then(r => r.ok ? r.json() : Promise.reject())
      .then(d => setStore(d.store || { version: 2, weeks: {} }))
      .catch(() => {                                     // refetch authoritative state on failure
        fetch('/api/assignments').then(r => r.json()).then(d => setStore(d.weeks ? d : { version: 2, weeks: {} })).catch(() => {});
      });
  }

  // Move the floating drag preview, holding the same grab point under the cursor
  // (so the tile travels relative to where you clicked, not top-left snapped). The
  // browser fires a final `drag` at (0,0) on release — ignore it so it doesn't jump.
  function positionGhost(x, y) {
    const g = dragGhost.current;
    if (!g || (x === 0 && y === 0)) return;
    g.style.left = `${x - grabOffset.current.x}px`;
    g.style.top = `${y - grabOffset.current.y}px`;
  }

  // Tear down a drag from whichever handler fires first (drop relocates the
  // source node, so dragend is unreliable — clean up in both).
  function cleanupDrag() {
    if (dragGhost.current) { dragGhost.current.remove(); dragGhost.current = null; }
    dragged.current = null;
    setDragOver(null);
  }

  function onDrop(owner) {
    const t = dragged.current;
    cleanupDrag();
    if (!t || !t.id || owner === ownerOf(t)) return;   // no-op / un-id'd legacy task
    // `from` is the agent's base assignment so the propagation diff compares
    // against the source markdown, not prior drags. For created tasks basePerson
    // is their home column, so dropping back there is still a no-op revert.
    postOp({ id: t.id, text: t.text, from: t.basePerson, to: owner });
  }

  const toggleDone = t => postOp({ id: t.id, text: t.text, status: isDone(t) ? 'open' : 'done' });
  const toggleDeleted = t => postOp({ id: t.id, text: t.text, deleted: !isDeleted(t) });
  // Step 2: confirm a marked (green/red) task off the current report immediately.
  const confirmRemove = t => postOp({ id: t.id, text: t.text, dismissed: true });
  // Pull a removed task all the way back to open (clears done/deleted/dismissed).
  const restoreTask = t => postOp({ id: t.id, text: t.text, status: 'open', deleted: false, dismissed: false });

  // Single creation path: the textarea's onBlur. Enter/blur-away commit; Esc
  // sets addCancel so the ensuing blur discards instead of creating.
  function commitNewTask(owner) {
    const cancelled = addCancel.current;
    addCancel.current = false;
    const text = newText.trim();
    setNewText('');
    setAddingIn(null);
    if (!cancelled && text) postOp({ text, to: owner, created: true });
  }

  function renderColumn(owner) {
    const all = tasks.filter(t => ownerOf(t) === owner);
    const closed = t => isDone(t) || isDeleted(t);
    // Removed (dismissed) tasks are off the report — hidden unless the toolbar
    // "show removed" toggle is on. done/deleted are still governed by hideClosed.
    const colTasks = all.filter(t => {
      if (isDismissed(t)) return showRemoved;
      return !(hideClosed && closed(t));
    });
    const openCount = all.filter(t => !closed(t) && !isDismissed(t)).length;
    const isTeam = owner === team;
    return (
      <div
        key={owner}
        className={`dv-col ${dragOver === owner ? 'dv-col--over' : ''} ${isTeam ? 'dv-col--team' : ''}`}
        onDragOver={e => { e.preventDefault(); if (dragOver !== owner) setDragOver(owner); }}
        onDragLeave={e => { if (e.currentTarget === e.target) setDragOver(null); }}
        onDrop={() => onDrop(owner)}
      >
        <h3 className="dv-h3">
          {isTeam ? 'Team tasks' : owner} <span className="dv-count">{openCount}</span>
          <button className="dv-add" title="Add a task to this column" onClick={() => { setAddingIn(owner); setNewText(''); }}>+</button>
        </h3>
        <div className="dv-col-body">
          {addingIn === owner && (
            <textarea
              className="dv-add-input"
              autoFocus
              rows={4}
              placeholder="New task… (Enter to add, Esc to cancel)"
              value={newText}
              onChange={e => setNewText(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); e.currentTarget.blur(); }
                else if (e.key === 'Escape') { addCancel.current = true; e.currentTarget.blur(); }
              }}
              onBlur={() => commitNewTask(owner)}
            />
          )}
          {colTasks.map((t, i) => {
            const moved = t.id && edits[t.id]?.to && edits[t.id].to !== t.basePerson;
            const done = isDone(t);
            const deleted = isDeleted(t);
            const dismissed = isDismissed(t);
            return (
              <div
                key={t.id || i}
                className={`dv-task ${t.id ? '' : 'dv-task--legacy'} ${moved ? 'dv-task--moved' : ''} ${done ? 'dv-task--done' : ''} ${deleted ? 'dv-task--deleted' : ''} ${dismissed ? 'dv-task--dismissed' : ''} ${t.created ? 'dv-task--created' : ''}`}
                draggable={!!t.id && !dismissed}
                onDragStart={e => {
                  if (dragGhost.current) { dragGhost.current.remove(); dragGhost.current = null; }
                  dragged.current = t;
                  e.dataTransfer.effectAllowed = 'move';
                  // Suppress the browser's native drag image (it's translucent and
                  // gradient-faded, not controllable) with a 1px blank canvas…
                  const blank = document.createElement('canvas');
                  blank.width = blank.height = 1;
                  e.dataTransfer.setDragImage(blank, 0, 0);
                  // …then follow the cursor with our own fully-opaque solid clone,
                  // holding the exact point within the tile where you grabbed it.
                  const card = e.currentTarget;
                  const rect = card.getBoundingClientRect();
                  grabOffset.current = { x: e.clientX - rect.left, y: e.clientY - rect.top };
                  const ghost = card.cloneNode(true);
                  ghost.classList.add('dv-drag-ghost');
                  ghost.style.width = `${card.offsetWidth}px`;
                  document.body.appendChild(ghost);
                  dragGhost.current = ghost;
                  positionGhost(e.clientX, e.clientY);
                }}
                onDrag={e => positionGhost(e.clientX, e.clientY)}
                onDragEnd={cleanupDrag}
                title={t.id ? 'Drag to reassign' : 'Re-run extract to enable reassignment'}
              >
                <span className="dv-task-text">{t.text}</span>
                {t.id && (
                  <span className="dv-task-actions">
                    {dismissed ? (
                      <button className="dv-task-btn" title="Restore to the list" onClick={e => { e.stopPropagation(); restoreTask(t); }}>↩</button>
                    ) : done ? (
                      <>
                        <button className="dv-task-btn" title="Mark open" onClick={e => { e.stopPropagation(); toggleDone(t); }}>↺</button>
                        <button className="dv-task-btn dv-task-btn--confirm" title="Confirm done — remove from this report" onClick={e => { e.stopPropagation(); confirmRemove(t); }}>Accept</button>
                      </>
                    ) : deleted ? (
                      <>
                        <button className="dv-task-btn" title="Restore task" onClick={e => { e.stopPropagation(); toggleDeleted(t); }}>↩</button>
                        <button className="dv-task-btn dv-task-btn--confirmdel" title="Confirm delete — remove from this report" onClick={e => { e.stopPropagation(); confirmRemove(t); }}>Delete</button>
                      </>
                    ) : (
                      <>
                        <button className="dv-task-btn" title="Mark resolved" onClick={e => { e.stopPropagation(); toggleDone(t); }}>✓</button>
                        <button className="dv-task-btn dv-task-btn--del" title="Delete task" onClick={e => { e.stopPropagation(); toggleDeleted(t); }}>✕</button>
                      </>
                    )}
                  </span>
                )}
                {dismissed
                  ? <span className="dv-task-from">removed from report</span>
                  : done
                  ? <span className="dv-task-from">resolved — Accept to remove now</span>
                  : deleted
                  ? <span className="dv-task-from">deleted — Delete to remove now, else drops next week</span>
                  : (moved || t.created) && <span className="dv-task-from">{t.created ? 'added here' : `moved from ${t.basePerson}`}</span>}
              </div>
            );
          })}
          {colTasks.length === 0 && addingIn !== owner && <div className="dv-col-empty">{isTeam ? 'unassigned tasks land here' : 'drop tasks here'}</div>}
        </div>
      </div>
    );
  }

  if (isNotConfigured(error)) return <EmptyState view="To-Do" />;
  if (error) return <div className="dv-error">{error}</div>;
  if (!data) return <div className="dv-loading">Loading to-dos…</div>;

  return (
    <div className="dv-root">
      <div className="dv-toolbar">
        <span className="dv-title">Action items</span>
        <div className="dv-weeknav">
          <button className="dv-weekbtn" disabled={week === activeWeek} title="Previous week"
            onClick={() => setViewWeek(shiftWeek(week, -7))}>◀</button>
          <span className="dv-weeklabel">week of {weekIso(week)}</span>
          <button className="dv-weekbtn" disabled={isFuture} title="Next week"
            onClick={() => setViewWeek(shiftWeek(week, 7))}>▶</button>
        </div>
        {week === activeWeek && <button className="dv-chip" onClick={() => selectFile(data.source)}>open file</button>}
        <button className={`dv-chip ${hideClosed ? 'dv-chip--on' : ''}`} onClick={() => setHideClosed(v => !v)}>
          {hideClosed ? 'show done/deleted' : 'hide done/deleted'}
        </button>
        {removedCount > 0 && (
          <button className={`dv-chip ${showRemoved ? 'dv-chip--on' : ''}`} onClick={() => setShowRemoved(v => !v)}>
            {showRemoved ? 'hide removed' : `show removed (${removedCount})`}
          </button>
        )}
        {pending > 0 && (
          <span className="dv-pending" title="Dashboard edits (reassign / resolve / delete / create) not yet folded into the source markdown — the /mot-sync propagation step applies them">
            {pending} pending sync
          </span>
        )}
        <GeneratedStamp data={data} onReload={reload} />
      </div>

      {isFuture && (
        <div className="dv-projnote">
          Projected report — carry-over of open tasks. Tasks resolved or deleted in the current week (and shown green there) drop off here; nothing is removed until <code>/mot-sync</code> publishes and rolls the week forward.
        </div>
      )}

      {/* Team column is a fixed sidebar OUTSIDE the scroller; members scroll in
          their own region to its right, so nothing ever passes under it. */}
      <div className="dv-board">
        {renderColumn(team)}
        <div className="dv-board-scroll">
          {columns.filter(o => o !== team).map(renderColumn)}
        </div>
      </div>

      <div className="dv-section">
        <h2 className="dv-h2">External / pending responses ({data.external_pending.length})</h2>
        <ul className="dv-bullets dv-bullets--two-col">
          {data.external_pending.map((e, i) => (
            <li key={i}><strong>{e.party}:</strong> {e.expected}</li>
          ))}
        </ul>
      </div>

      <div className="dv-section">
        <h2 className="dv-h2">Key dates</h2>
        <table className="dv-table dv-table--full">
          <tbody>
            {data.key_dates.map((k, i) => {
              const d = k.date_iso ? -daysSince(k.date_iso) : null; // days until
              return (
                <tr key={i}>
                  <td className="dv-date">{k.date_raw}</td>
                  <td>{k.event}</td>
                  <td className="dv-date">
                    {d == null ? '' : d < 0 ? `${-d}d ago` : d === 0 ? 'today' : `in ${d}d`}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Calendar — events agenda, grouped by month
//
// Read-only projection of __Operations/Documentation/Events.md (→ events.json,
// regenerated by mot-tools.js extract). Events are sparse (~a dozen across many
// months), so an agenda grouped by month reads better than a grid: upcoming is
// listed first with the next event flagged + a countdown; past is dimmed behind
// a toggle. The participation gate (Sync_Content_Schema §H) keeps unconfirmed
// event advertisements out of this feed entirely — only confirmed events appear.
// ---------------------------------------------------------------------------

const CAL_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];
const CAL_WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

// Parse "YYYY-MM-DD" to a local-midnight Date (stable day math, no TZ drift).
function calParseDate(iso) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d);
}

// "today" / "tomorrow" / "in 5d" / "yesterday" / "3d ago" from an ISO date.
function calRelative(iso) {
  const since = daysSince(iso);            // days since (negative = future)
  if (since == null) return '';
  const until = -since;
  if (until === 0) return 'today';
  if (until === 1) return 'tomorrow';
  if (until === -1) return 'yesterday';
  return until > 0 ? `in ${until}d` : `${-until}d ago`;
}

// Group an already-sorted event list into [{key, label, events:[]}] by month.
function calGroupByMonth(events) {
  const groups = [];
  for (const e of events) {
    const key = e.date.slice(0, 7);
    let g = groups[groups.length - 1];
    if (!g || g.key !== key) {
      g = { key, label: `${CAL_MONTHS[+key.slice(5) - 1]} ${key.slice(0, 4)}`, events: [] };
      groups.push(g);
    }
    g.events.push(e);
  }
  return groups;
}

function CalEventRow({ e }) {
  const undated = !e.date;
  return (
    <div className={`cal-event ${e.isPast ? 'cal-event--past' : ''} ${e.isNext ? 'cal-event--next' : ''} ${e.isToday ? 'cal-event--today' : ''} ${undated ? 'cal-event--undated' : ''}`}>
      <div className="cal-datechip" title={undated ? (e.date_raw || 'no date yet') : e.date}>
        {undated
          ? <span className="cal-day cal-day--tbd">TBD</span>
          : (<>
              <span className="cal-dow">{CAL_WEEKDAYS[e.dt.getDay()]}</span>
              <span className="cal-day">{e.dt.getDate()}</span>
            </>)}
      </div>
      <div className="cal-event-body">
        <span className="cal-event-text">{e.event}</span>
        {e.isNext && <span className="cal-nextflag">next</span>}
      </div>
      <span className="cal-rel">{calRelative(e.date)}</span>
    </div>
  );
}

function CalMonthGroups({ groups }) {
  return groups.map(g => (
    <div key={g.key} className="cal-month">
      <h3 className="cal-month-head">{g.label}</h3>
      <div className="cal-month-body">
        {g.events.map((e, i) => <CalEventRow key={e.date + i} e={e} />)}
      </div>
    </div>
  ));
}

export function CalendarView() {
  const { selectFile } = useDashboard();
  const [data, error, reload] = useData('events');
  const [showPast, setShowPast] = usePersistentState('cal-show-past', false);

  const { upcoming, past, undated, todayLabel } = useMemo(() => {
    if (!data?.events) return { upcoming: [], past: [], undated: [], todayLabel: '' };
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const dated = data.events
      .filter(e => e.date && /^\d{4}-\d{2}-\d{2}$/.test(e.date))
      .map(e => {
        const dt = calParseDate(e.date);
        return { ...e, dt, isPast: dt < today, isToday: dt.getTime() === today.getTime() };
      })
      .sort((a, b) => a.dt - b.dt);
    const up = dated.filter(e => !e.isPast);
    if (up.length) up[0] = { ...up[0], isNext: true };        // first upcoming = "next"
    const pastDesc = dated.filter(e => e.isPast).reverse();   // most-recent past first
    const undatedEvents = data.events.filter(e => !e.date);   // confirmed but no date yet
    const tl = `${CAL_WEEKDAYS[today.getDay()]} ${today.getDate()} ${CAL_MONTHS[today.getMonth()].slice(0, 3)} ${today.getFullYear()}`;
    return { upcoming: calGroupByMonth(up), past: calGroupByMonth(pastDesc), undated: undatedEvents, todayLabel: tl };
  }, [data]);

  if (isNotConfigured(error)) return <EmptyState view="Calendar" />;
  if (error) return <div className="dv-error">{error}</div>;
  if (!data) return <div className="dv-loading">Loading calendar…</div>;

  const upCount = upcoming.reduce((n, g) => n + g.events.length, 0);
  const pastCount = past.reduce((n, g) => n + g.events.length, 0);

  return (
    <div className="dv-root">
      <div className="dv-toolbar">
        <span className="dv-title">Calendar</span>
        <span className="dv-count">{upCount} upcoming</span>
        {undated.length > 0 && <span className="dv-count">· {undated.length} undated</span>}
        {pastCount > 0 && (
          <button className={`dv-chip ${showPast ? 'dv-chip--on' : ''}`} onClick={() => setShowPast(v => !v)}>
            {showPast ? 'hide past' : `show past (${pastCount})`}
          </button>
        )}
        {data.source && <button className="dv-chip" onClick={() => selectFile(data.source)}>open Events.md</button>}
        <GeneratedStamp data={data} onReload={reload} />
      </div>

      <div className="cal-today">Today · {todayLabel}</div>

      {upCount === 0 && undated.length === 0
        ? <div className="dv-empty">No upcoming events.</div>
        : <CalMonthGroups groups={upcoming} />}

      {undated.length > 0 && (
        <div className="cal-month">
          <h3 className="cal-month-head cal-month-head--undated">No date yet</h3>
          <div className="cal-month-body">
            {undated.map((e, i) => <CalEventRow key={'u' + i} e={e} />)}
          </div>
        </div>
      )}

      {showPast && pastCount > 0 && (
        <>
          <div className="cal-divider">Past</div>
          <CalMonthGroups groups={past} />
        </>
      )}
    </div>
  );
}
